import { XAccountSchema, type XAccount } from '../../types/x-bookmarks';
import { assertExplicitSourceSync } from '../../types/source-sync';
import { parseCosmosUrl } from '../../types/cosmos';
import { cosmosPage, cosmosRequest } from './cosmosPage';
import { isRemoteProfileProvider } from '../../types/design-profile';
import { isXBookmarkUrl, xPage } from './xPage';
import {
  ProviderRateLimit,
  throwIfRateLimited,
} from '../../utils/ProviderRateLimit';
import { IntegrationsClient } from '../IntegrationsClient';
import { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import type { ProfileRuntime } from '../../types/design-profile';
import type { ProfileMedia } from './ProfileMedia';
import { PROFILE_IMAGE_BYTES } from './ProfileMedia';
import { pinterestPage, arenaPage } from './boardPage';
import { validateInspirationUrl } from '../../agent-variants/sourceContext';
import { errorMessage } from '../../utils/errorMessage';
import { failureReasonCode } from '../../utils/failureReason';

const DOWNLOAD_TIMEOUT_MS = 20_000;
const MAX_REDIRECTS = 5;
const MEDIA_HOSTS = ['pinimg.com', 'are.na', 'cloudfront.net', 'amazonaws.com'];

export const reconnectRequiredMessage = (provider: string): string =>
  `Reconnect ${provider} in Rivet, then retry this import`;

export class ProfileImports {
  constructor(
    private readonly records: ProfileRecords,
    private readonly media: ProfileMedia,
    private readonly isCurrentAccount: () => boolean,
    private readonly client: Pick<
      IntegrationsClient,
      'fetchPinterest' | 'fetchArena' | 'fetchXBookmarks' | 'fetchCosmos'
    > = new IntegrationsClient(),
  ) {}

  private startImport(
    source: ReturnType<ProfileRecords['source']>,
    runtime: ProfileRuntime,
  ) {
    assertExplicitSourceSync(source.syncMode);
    const job = this.records.startImport({ sourceId: source.id, runtime });
    return { source, job };
  }

  connect({
    url,
    runtime,
    xAccount,
  }: {
    url: string;
    runtime: ProfileRuntime;
    xAccount?: XAccount;
  }) {
    if (isXBookmarkUrl(url)) {
      const account = XAccountSchema.parse(xAccount);
      const source = this.records.addSource({
        provider: 'x',
        remoteId: `bookmarks:${account.id}`,
        title: `@${account.username} bookmarks`,
        url: 'https://x.com/i/bookmarks',
      });
      return this.startImport(source, runtime);
    }
    const parsed = new URL(url);
    const host = parsed.hostname.toLowerCase();
    if (host === 'cosmos.so' || host === 'www.cosmos.so') {
      const collection = parseCosmosUrl(url);
      const source = this.records.addSource({
        provider: 'cosmos',
        remoteId: collection.url,
        title: collection.subcollectionSlug ?? collection.slug,
        url: collection.url,
      });
      return this.startImport(source, runtime);
    }
    const isPinterest =
      host === 'pinterest.com' ||
      host.endsWith('.pinterest.com') ||
      host === 'pin.it' ||
      host === 'www.pin.it';
    const isArena = host === 'are.na' || host.endsWith('.are.na');
    if (
      parsed.protocol !== 'https:' ||
      parsed.username ||
      parsed.password ||
      (!isPinterest && !isArena)
    )
      throw new Error(
        'Connect an HTTPS Pinterest pin or board, Are.na block or channel, public Cosmos collection, or https://x.com/i/bookmarks without credentials',
      );
    parsed.search = '';
    parsed.hash = '';
    const source = this.records.addSource({
      provider: isPinterest ? 'pinterest' : 'arena',
      remoteId: parsed.toString(),
      title:
        parsed.pathname.split('/').filter(Boolean).pop() ?? 'Reference source',
      url: parsed.toString(),
    });
    return this.startImport(source, runtime);
  }

  async enumerate(
    jobId: string,
    signal: AbortSignal,
    onPageSaved: () => void = () => undefined,
  ): Promise<void> {
    while (true) {
      signal.throwIfAborted();
      if (!this.isCurrentAccount())
        throw new Error(
          'Profile import paused because the active account changed',
        );
      const job = this.records
        .jobs()
        .find((candidate) => candidate.id === jobId);
      if (!job || job.state !== 'pending' || job.isEnumerated) return;
      const source = this.records.source(job.sourceId);
      if (!source.url)
        throw new Error('The connected source has no provider URL');
      if (!isRemoteProfileProvider(source.provider))
        throw new Error('This source does not support remote imports');
      const url = source.url;
      const provider = source.provider;
      const readPage = async () => {
        switch (provider) {
          case 'cosmos': {
            const result = await this.client.fetchCosmos({
              url,
              ...cosmosRequest(job.cursor),
              signal,
            });
            this.requirePage(result, provider);
            return cosmosPage(result, job.cursor);
          }
          case 'pinterest': {
            const result = await this.client.fetchPinterest(
              url,
              { ...(job.cursor ? { cursor: job.cursor } : {}) },
              signal,
            );
            this.requirePage(result, source.provider);
            return pinterestPage(result, job.cursor);
          }
          case 'arena': {
            const result = await this.client.fetchArena(
              url,
              Number(job.cursor ?? 1),
              signal,
            );
            this.requirePage(result, source.provider);
            return arenaPage(result, job.cursor);
          }
          case 'x': {
            const expectedAccountId = source.remoteId.replace(
              /^bookmarks:/,
              '',
            );
            const result = await this.client.fetchXBookmarks({
              expectedAccountId,
              cursor: job.cursor ?? undefined,
              signal,
            });
            this.requirePage(result, source.provider);
            return xPage(result, job.cursor, expectedAccountId);
          }
          default: {
            const unsupported: never = provider;
            throw new Error(`Unsupported provider: ${unsupported}`);
          }
        }
      };
      const page = await readPage();
      signal.throwIfAborted();
      if (!this.isCurrentAccount())
        throw new Error('Profile account changed during enumeration');
      if (
        this.records.jobs().find((candidate) => candidate.id === jobId)
          ?.state !== 'pending'
      )
        return;
      this.records.saveImportPage({
        jobId,
        references: page.references,
        cursor: page.cursor,
        isComplete: page.isComplete,
        total: page.total,
        remoteId: page.remoteId,
        title: page.title,
        collection: page.collection,
      });
      onPageSaved();
      if (page.isComplete) return;
    }
  }

  async download(
    jobId: string,
    signal: AbortSignal,
    onReferenceSaved: () => void = () => undefined,
  ): Promise<void> {
    const job = this.records.jobs().find((candidate) => candidate.id === jobId);
    if (!job) throw new Error('Unknown profile import');
    for (const reference of this.records.references(job.sourceId)) {
      signal.throwIfAborted();
      if (!this.isCurrentAccount())
        throw new Error(
          'Profile import paused because the active account changed',
        );
      if (!this.isPending(jobId)) return;
      if (reference.unsupportedReason || !reference.remoteImages?.length)
        continue;
      let current = reference;
      try {
        for (const [index, url] of reference.remoteImages.entries()) {
          const existing = current.media[index];
          if (existing) {
            try {
              await this.media.resolve(existing);
              continue;
            } catch {}
          }
          const image = await this.media.put(
            await this.downloadImage(url, signal),
          );
          signal.throwIfAborted();
          if (!this.isCurrentAccount())
            throw new Error('Profile account changed during download');
          if (!this.isPending(jobId)) return;
          const images = [...current.media];
          images[index] = {
            ...image,
            representation:
              reference.remoteImageRepresentations?.[index] ?? 'image',
          };
          current = this.records.saveReference({
            sourceId: job.sourceId,
            reference: { ...current, media: images },
          });
        }
        if (current !== reference) onReferenceSaved();
        this.records.clearFailure(reference.id, 'download');
      } catch (error) {
        signal.throwIfAborted();
        if (!this.isCurrentAccount()) throw error;
        if (error instanceof ProviderRateLimit) throw error;
        if (!this.isPending(jobId)) return;
        this.records.saveFailure({
          jobId,
          referenceId: current.id,
          revision: current.revision,
          stage: 'download',
          error: errorMessage(error, 'Image download failed'),
          reasonCode: failureReasonCode(error),
        });
      }
    }
  }

  private requirePage(
    result: {
      status: string;
      reason?: string;
      retryAfterMs?: number;
      message?: string;
    },
    provider: string,
  ): void {
    if (result.status === 'error' && result.reason === 'rate_limited')
      throw new ProviderRateLimit(result.retryAfterMs);
    if (result.status !== 'ok')
      throw new Error(
        result.status === 'not_connected'
          ? reconnectRequiredMessage(provider)
          : result.message,
      );
  }

  private isPending(jobId: string): boolean {
    return (
      this.records.jobs().find((job) => job.id === jobId)?.state === 'pending'
    );
  }

  private async downloadImage(
    raw: string,
    cancellation: AbortSignal,
  ): Promise<Buffer> {
    const signal = AbortSignal.any([
      cancellation,
      AbortSignal.timeout(DOWNLOAD_TIMEOUT_MS),
    ]);
    let url = raw;
    for (let redirects = 0; redirects <= MAX_REDIRECTS; redirects += 1) {
      const validation = validateInspirationUrl(url);
      if (
        !validation.ok ||
        validation.url.protocol !== 'https:' ||
        !(
          validation.url.hostname === 'pbs.twimg.com' ||
          validation.url.hostname === 'cdn.cosmos.so' ||
          MEDIA_HOSTS.some(
            (host) =>
              validation.url.hostname === host ||
              validation.url.hostname.endsWith(`.${host}`),
          )
        )
      )
        throw new Error(
          'Reference media URL is outside the supported provider hosts',
        );
      const response = await fetch(url, { redirect: 'manual', signal });
      if (response.status >= 300 && response.status < 400) {
        const location = response.headers.get('location');
        await response.body?.cancel();
        if (!location)
          throw new Error('Reference media redirect has no destination');
        url = new URL(location, url).toString();
        continue;
      }
      await throwIfRateLimited(response);
      if (!response.ok || !response.body) {
        await response.body?.cancel();
        throw new Error(
          `Reference image download failed (${response.status}); retry this import`,
        );
      }
      if (
        Number(response.headers.get('content-length')) > PROFILE_IMAGE_BYTES
      ) {
        await response.body.cancel();
        throw new Error('Reference image exceeds the media budget');
      }
      const reader = response.body.getReader();
      const chunks: Buffer[] = [];
      let size = 0;
      while (true) {
        const next = await reader.read();
        if (next.done) break;
        size += next.value.length;
        if (size > PROFILE_IMAGE_BYTES) {
          await reader.cancel();
          throw new Error('Reference image exceeds the media budget');
        }
        chunks.push(Buffer.from(next.value));
      }
      return Buffer.concat(chunks);
    }
    throw new Error('Reference image exceeded the redirect limit');
  }
}
